/**
 * An icon from Phosphor Icons (https://phosphoricons.com, MIT License, © 2023 Phosphor Icons; full notice in
 * assets/licenses/phosphor-icons.txt). Only the icons the app uses are copied, in three weights, on
 * Phosphor's 256×256 grid. Shapes are filled outlines, so they stay crisp at any size.
 */
@Immutable
class KtIcon(val name: String, val regular: List<String>, val bold: List<String>, val fill: List<String>) {
    /**
     * [strokeWidth] picks the weight like the old stroke widths did: up to 2.3 = regular (rows, buttons),
     * from 2.4 = bold (small chips, checkmarks); [filled] = the solid version (selected / saved states).
     */
    fun toImageVector(strokeWidth: Float = 2.2f, filled: Boolean = false): ImageVector =
        ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 256f, viewportHeight = 256f)
            .apply { weight(strokeWidth, filled).forEach { addPath(pathData = addPathNodes(it), fill = SolidColor(Color.Black)) } }
            .build()

    fun weight(strokeWidth: Float, filled: Boolean): List<String> = when {
        filled -> fill
        strokeWidth >= 2.4f -> bold
        else -> regular
    }
}

/** Draws a [KtIcon]. Pass a [contentDescription] only when the icon stands alone (icon buttons). */
@Composable
fun KonstanzIcon(
    icon: KtIcon,
    contentDescription: String?,
    modifier: Modifier = Modifier,
    size: Dp = 24.dp,
    tint: Color = LocalContentColor.current,
    /** Weight: up to 2.3 regular, from 2.4 bold (see [KtIcon.toImageVector]). */
    strokeWidth: Float = 2.2f,
    /** The solid version, like the navigation arrow on "Go" buttons or a saved star. */
    filled: Boolean = false,
) {
    val vector = remember(icon, strokeWidth, filled) { icon.toImageVector(strokeWidth, filled) }
    Icon(vector, contentDescription, modifier.size(size), tint = tint)
}

